window.VD=window.VD||{};window.VD["vw/amarok-2h"]={"amarok-2h-facelift-activate-discover-hidden-menu":"<p><strong>Purpose:</strong> Activates the green hidden menu (green menu, hidden menu, testmode, engineer mode) on Discover MIB2.  </p>\n<p>/!\\ Caution: Making certain changes in the hidden menu may cause MIB2 to freeze or no longer start /!\\</p>\n<p><em>For <em><em>Amarok Facelift after 2015</em></em> (Radio screen like Golf 7).  </em><br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong> then click on<strong>“5F – Electr. information</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“S12345</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Developer mode</strong>”.<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu at the bottom<br/>of the page.<br/>On this menu, choose the value<strong>“activated</strong>”.</p>\n<p><em>Restart MIB2, keep MENU button pressed until testmode menu appears</em><br/></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/developermode-bfa51f40.webp\"/></figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/developermode2-1024x576-7a0c833c.webp\"/></figure>","amarok-2h-facelift-activate-off-road-mode-on-discover-pq":"<p><strong>Purpose:</strong> to add Offroad mode to Discover PQ with navigation.  <br/><br/><br/><strong>Warning! There are 3 lines of coding to do here. </strong> <br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong> then click on<strong>“5F – Electr. information</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“20103</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Car_Function_List_BAP_Gen2-compass_0x15</strong>”.<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu at the bottom<br/>of the page.<br/>On this menu, select<strong>“active</strong>” and confirm.<br/><br/><strong>Line 2:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong> then click on<strong>“5F – Electr. information</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“20103</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Car_Function_Adaptations_Gen2-menu_display_Compass</strong>”.<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu at the bottom<br/>of the page.<br/>On this menu, select<strong>“active</strong>” and confirm.<br/><br/><strong>Line 3:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong> then click on<strong>“5F – Electr. information</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“20103</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Car_Function_Adaptations_Gen2-menu_display_Compass_over-threshold_high</strong>”.<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu at the bottom<br/>of the page.<br/>On this menu, select<strong>“active</strong>” and confirm.</p>\n<hr/>\n<p>Restart the Discover Media PQ (hold down the ON/OFF button for at least 5 seconds).</p>\n<p>Depending on your hardware and firmware, the off-road menu may appear directly in the Menu, or it may be hidden:<br/>Press the VOICE-MENU-NAV buttons to access the secret menu, where you’ll now find the OFFROAD screen:  </p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/offroadpq-1024x768-39023fd7.webp\"/></figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/offroadmenupq-1024x619-dc3e8b4c.webp\"/></figure>\n<figure>\n</figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/offroad-1024x631-441bee99.webp\"/></figure>","amarok-2h-facelift-activate-reversing-camera-retrofit":"<p><strong>Purpose:</strong> Enables the rearview camera after it has been installed on the Discover MIB2 PQ (retrofit).</p>\n<p><em>For <em><em>Amarok Facelift after 2015</em></em> (Radio screen like golf 7).</em><br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong> then click on<strong>“5F – Electr. information</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“20103</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Coding – 07</strong>” then click on<strong>“Long Coding Helper</strong>“.<br/><br/><strong>6</strong> – Select byte <strong>19</strong><br/>. Then set bit <strong>4</strong> to “Rear View Camera (RVC) Low installed (PR-KA1).”</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/C25A41FA-66F7-4FC9-B7F4-1761395A1D01-1024x483-11bbd3cf.webp\"/></figure>\n<p><strong><strong><strong>Line 2 (Optional, if parking assist is available)</strong> <strong>:</strong></strong></strong><br/><br/><strong>3</strong> – Click “<strong>Select</strong>,” then click “<strong>10 – Parking Assistance</strong>.”<br/><br/><strong>4</strong> – Click on<strong>“Coding – 07</strong>” then click on<strong>“Long Coding Helper</strong>“.<br/><br/><strong>5 – </strong> Select byte <strong>0</strong><br/>. Then set bit <strong>5</strong> to “Rear View Camera installed.”</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/CA86A611-2F74-4201-B791-7A74BC107A01-1024x482-c9f00e16.webp\"/></figure>\n<p><strong>Hardware upgrade :</strong></p>\n<p>The camera’s video cable is connected to the infotainment control unit. It is installed in the glovebox.   <br/><br/>The 2 pins of the reversing camera are used in the 12-pin quadlock (blue). Usable cable set: Part no. 000 979 009 E <br/><br/>Quadblock Assignment :<br/><br/>Pin 6 = video line<br/>Pin 12 = shielding</p>","amarok-2h-facelift-deactivate-mirrorlink":"<p><strong>Purpose:</strong> Allows you to disable or remove MirrorLink from App-Connect on the MIB Discover PQ. The MirrorLink service has not been natively available on Android since June 1, 2020. For a direct connection to Android Auto.   <br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong> then click on<strong>“5F – Electr. information</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“20103</strong>“.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Vehicle configuration-Mirror_link</strong>“.<br/><br/><strong>7</strong> – On the same page, you’ll find a second drop-down menu at the bottom<br/>of the page.<br/>On this menu, select<strong>“Disabled</strong>” and confirm.</p>","amarok-2h-facelift-disable-am-frequency-on-discover":"<p><strong>Purpose:</strong> to deactivate the AM radio frequency on the Discover PQ (the AM radio frequency is rarely used, unlike the FM radio frequency). <br/><em><em>For Amarok Facelift after 2015 (Radio display like Golf 7). </em></em> </p>\n<p><br/><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select”</strong> then click on<strong>“5F – Electr. information</strong>”.</p>\n<p><strong>4</strong> – Click on “<strong>Coding – 07</strong>”.</p>\n<p><strong>5</strong> – Click on “<strong>Long Coding Helper</strong>” .</p>\n<p><strong>6</strong> – Select Byte <strong>14</strong></p>\n<p>Set bit <strong>1</strong> <strong>“AM_disable</strong></p>\n<figure>\n</figure>","amarok-2h-facelift-fan-speed-display-on-air-conditioning-in-auto-mode":"<p><strong>Purpose:</strong> to display fan speed when automatic air-conditioning mode is activated. (Climatronic fan speed display Auto mode)  <br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>” then click on<strong>“08 – Climatronic</strong>” /<strong>“08 – Auto HVAC</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Coding – 07</strong>” then click on<strong>“Long Coding Helper</strong>”.<br/><br/><strong>5</strong> – Select byte<strong>“11</strong>”<br/>Then check Bit<strong>“6</strong>”:<strong>“Blower Status Display in Auto-Mode active</strong>”.<br/></p>\n<figure>\n</figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/5G0-907-044-R_Module08_Byte11_v2-939963df.webp\"/></figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/affichageclimautomqb-f32e9600.webp\"/></figure>","amarok-2h-activate-comfort-turn-signals":"<p><strong>Function:</strong> Activates the convenience turn signals.  </p>\n<p><em>(By default, the number of flashes is 3. You can change this value to any number between 1 and 5.) </em>)  <br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click “ <strong>Select</strong>,” then click “ <strong>09 – Cent. Elect.”</strong><br/><br/><strong>4 – </strong>Click on<strong> “Coding – 07” </strong></p>\n<p><strong>5</strong> – Select module “0” and click “Long Coding Helper”:</p>\n<p><em>Byte<strong> 12: </strong></em><br/><em>Bit <strong>5</strong>: Check <strong>“Comfort Turn Signals active</strong> ”</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/6R0-937-088-B_Module09_Byte12-011f47aa.webp\"/></figure>","amarok-2h-activate-coming-home-leaving-home":"<p><strong>Purpose: </strong>To activate Coming-Home / Leaving-Home.  </p>\n<p>(To work properly, the vehicle must be equipped with a light sensor. Headlight switch must be in “Auto” position.   <br/>Without the light sensor, it will be necessary to make a headlight call to activate the coming-home).  </p>\n<p><strong>Procedure: </strong><br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Coding 07</strong>”.</p>\n<p><strong>5</strong> – Select the “0” module and click on “Long Coding Helper”:</p>\n<p>Byte <strong>10 </strong>: <br/>Bit <strong>1</strong>: Check “Leaving-Home (LH) active”<br/>Bit <strong>2</strong>: Check “Coming-Home (CH) active”.</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/vw-polo-6r-cominghome-b8af74dc.webp\"/></figure>","amarok-2h-activate-daytime-running-lights-drl":"<p><strong>Purpose:</strong> to activate the daytime running lights (DRL).  </p>\n<p><strong>Procedure: </strong><br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Coding 07</strong>”.</p>\n<p><strong>5</strong> – Select the “0” module and click on “Long Coding Helper”:</p>\n<p><em>Byte <strong>23</strong>: </em><br/><em>Bit <strong>6 : </strong> Check Function “Daytime Running Light (DRL)” active</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/6R0-937-088-B_Module09_Byte23-e94f1178.webp\"/></figure>\n<p><strong>Line 2:</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Coding 07</strong>”.</p>\n<p><strong>5</strong> – Select the “0” module and click on “Long Coding Helper”:</p>\n<p><em>Byte <strong>12 </strong>: </em><br/><em>Bit <strong>1</strong>: Tick “Daytime Running Light (DRL) adjustable (Manually AND/OR instrument Cluster)”.</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/6R0-937-088-B_Module09_Byte12-2c0d5984.webp\"/></figure>","amarok-2h-activate-hidden-menu-rns-315":"<p><strong>Purpose</strong>: to activate the hidden menu in RNS 315.  </p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition, then run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/> 3 – Click on “<strong>Select”</strong>, then click on “<strong>Select</strong>”, then click on “<strong>Select</strong>”. <strong>Procedure:</strong> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket. <strong><strong>“37 – Navigation</strong></strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Adaptation – 10</strong>”.</p>\n<p><strong>5</strong> – Select <em><strong>Developer mode (temporary)</strong> </em>then set the value to <strong><em>Enabled</em></strong></p>\n<p><em>Restart RNS 315.</em></p>\n<p><em>To launch the Hidden Menu, press SETUP (for 6s)</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/3C0-035-279_Module37_Adaptation_Developer_mode_tem-59109da4.webp\"/></figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/rns-315-bt-8b82eb41.webp\"/></figure>","amarok-2h-activate-hidden-menu-rns-510":"<p><strong>Purpose</strong>: Activates the hidden menu in RNS 510.  </p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition, then run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/> 3 – Click on ” <strong>Select”</strong>, then click on ” <strong>Select</strong> ” and run the VCDS program.<strong><strong>56 – Radio</strong></strong>” .</p>\n<p><strong>4</strong> – Click on “<strong>Adaptation – 10</strong>”.</p>\n<p><strong>5</strong> – Choose <em><strong>Channel 50</strong> </em>then set the value to <strong>1</strong></p>\n<p><em>Restart the RNS 510.</em></p>\n<p><em>To launch the Hidden Menu, press SETUP (for 6s)</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/1T0-035-680-C_Module37_Adaptation_Channel50-1a7d6a90.webp\"/></figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/rns510-1024x821-d0438887.webp\"/></figure>","amarok-2h-activate-interior-lighting-on-key-removal":"<p><strong>Purpose: </strong>to activate the interior lighting when the key is removed from the neiman.  </p>\n<p><strong>Procedure: </strong><br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Coding 07</strong>”.</p>\n<p><strong>5</strong> – Select the “0” module and click on “Long Coding Helper”:</p>\n<p>Byte <strong>12</strong>:<br/>Bit<strong> 2</strong>: check “Interior Light after ignition Key removal active”.</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/6R0-937-088-B_Module09_Byte12-2c0d5984.webp\"/></figure>","amarok-2h-activate-rain-sensor":"<p><strong>Purpose</strong>: Enables the rain sensor.  </p>\n<p><strong>Procedure:</strong> <br/>1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/>2 – Switch on the ignition, then run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/>3 – Click on ” <strong>Select</strong> “, then click on ” <strong>09 – Cent. Elect.</strong>” . Switch on the ignition and run the VCDS program. 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>4</strong> – Click on “ <strong>Code 07.”</strong></p>\n<p><strong>5</strong> – Click on “Long Coding Helper” :</p>\n<p><strong>6</strong> – In the window that appears, select,</p>\n<p><em>Byte <strong>14</strong>: </em> <br/><em>Bit <strong>1</strong>: Check “Rain Sensor Function Active”</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/6R0-937-088-B_Module09_Byte14-cd640f80.webp\"/></figure>\n<p><strong>Line 2: </strong></p>\n<p><strong>3</strong> – Click “ <strong>Select</strong>,” then click “ <strong>09 – Cent. Elect.”</strong></p>\n<p><strong>4</strong> – Click on “ <strong>Code 07.”</strong></p>\n<p><strong>5</strong> – Select the “RLS” module and click “Long Coding Helper”:</p>\n<p><em><em>Byte <strong>4</strong>: </em> </em><br/><em><em>Bit <strong>5</strong>: Uncheck “Rain Sensor Inactive”</em></em></p>","amarok-2h-activate-reversing-camera-retrofit":"<p><strong>Purpose:</strong> Enables the rearview camera after it has been installed on the RCD 510/330/360/440 and RNS 315/510 (retrofit).  <br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click “<strong>Select</strong>,” then click “<strong>37 – Navigation</strong> ” (RNS) or “<strong>56 – Radio</strong>” (RCD)<br/><br/><strong>4</strong> – Click on<strong>“Coding – 07</strong>” then click on<strong>“Long Coding Helper</strong>“.<br/><br/><strong>5 – </strong> Select byte <strong>3</strong><br/>. Then set bit <strong>6</strong> to “Rear View Camera (RVC) installed/active.”</p>\n<p><strong><strong><strong>Line 2 (Optional, if parking assist is available)</strong> <strong>:</strong></strong></strong><br/><br/><strong>3</strong> – Click “<strong>Select</strong>,” then click “<strong>10 – Parking Assistance</strong>.”<br/><br/><strong>4</strong> – Click on<strong>“Coding – 07</strong>” then click on<strong>“Long Coding Helper</strong>“.<br/><br/><strong>5 – </strong> Select byte <strong>0</strong><br/>. Then set bit <strong>5</strong> to “Rear View Camera installed.”</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/CA86A611-2F74-4201-B791-7A74BC107A01-1024x482-c9f00e16.webp\"/></figure>\n<p><br/><strong>Hardware upgrade :</strong></p>\n<p>The camera’s video cable is connected to the infotainment control unit. It is installed in the glovebox.   <br/><br/>The two pins from the backup camera are used in the 12-pin Quadlock connector (blue).<br/><br/>Quadblock Assignment :<br/><br/>Pin 6 = video line<br/>Pin 12 = shielding</p>","amarok-2h-activate-rns-510-voice-control":"<p><strong>Purpose</strong>: to activate voice control on the RNS 510 (SDS).  </p>\n<p><strong>ATTENTION:</strong> RNS 510 firmware must be version v2660.</p>\n<p>Activating voice control brings up the “Voice control” menu in the RNS 510’s SETUP menu.</p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition, then run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/> 3 – Click on “<strong>Select”</strong>, then click on “<strong>Select</strong>”, then click on “<strong>Select</strong>”. <strong>Procedure:</strong> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket. <strong><strong>“37 – Navigation</strong></strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Coding 07</strong>”.</p>\n<p><strong>5</strong> – Select the “0” module and click on “Long Coding Helper”:</p>\n<p>Byte <strong>3</strong>, check the box for<strong>“Bit 1: Microphone Diagnostics active</strong>”.</p>\n<p>Byte <strong>7</strong>, uncheck the box for<strong>“Bit 1: Voice Control inactive</strong>”.<br/></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/RNS510_Menu_Commande_Vocale-bf5955d7.webp\"/></figure>\n<p>To install the microphone, connect the microphone lead to the rear of the RNS 510. Connect to pins (Mic-)C1 and (Mic+)C7. </p>","amarok-2h-activate-wiper-change-mode":"<p><strong>Function</strong>: Activates the intermittent mode for the front windshield wipers.  </p>\n<p><strong>Procedure:</strong> <br/>1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/>2 – Switch on the ignition, then run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/>3 – Click on ” <strong>Select</strong> “, then click on ” <strong>09 – Cent. Elect.</strong>” . Switch on the ignition and run the VCDS program. 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>4</strong> – Click on “ <strong>Code 07.”</strong></p>\n<p><strong>5</strong> – Click on “Long Coding Helper” :</p>\n<p><strong>6</strong> – In the window that appears, select,</p>\n<p><em>Byte <strong>14</strong>: </em><br/><em>Bit<strong> 2</strong>: Check “Service Position for Front Wiper active”</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/6R0-937-088-B_Module09_Byte14-cd640f80.webp\"/></figure>\n<p><strong>Line 2: </strong></p>\n<p><strong>3</strong> – Click “ <strong>Select</strong>,” then click “ <strong>09 – Cent. Elect.”</strong></p>\n<p><strong>4</strong> – Click on “<strong>Adaptation – 10</strong>” .</p>\n<p><strong>5</strong> – Select <strong>Channel 23</strong>: <em>Set the value to 1.</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/6R0-937-088-B_Module09_Adaptation_channel231-91e9521d.webp\"/></figure>","amarok-2h-activating-bluetooth-on-rns-315":"<p><strong>Purpose</strong>: to activate Bluetooth on the RNS 315.  </p>\n<p><strong>ATTENTION: Not all RNS-315 are equipped with a Bluetooth module.</strong> </p>\n<figure><table><thead><tr><td>Module compatibility list</td></tr></thead><tbody><tr><td>3C0 035 279</td><td>Yes</td></tr><tr><td>3C0 035 279 A</td><td>Yes</td></tr><tr><td>3C0 035 279 B</td><td>Yes</td></tr><tr><td>3C0 035 279 C</td><td>Yes (conditional)</td></tr><tr><td>3C0 035 279 D</td><td>No</td></tr><tr><td>3C0 035 279 E</td><td>No</td></tr><tr><td>3C0 035 279 F</td><td>No</td></tr><tr><td>3C0 035 279 G</td><td>Yes</td></tr><tr><td>3C0 035 279 H</td><td>Yes</td></tr><tr><td>3C0 035 279 J</td><td>No</td></tr><tr><td>3C0 035 279 K</td><td>No</td></tr></tbody></table></figure>\n<p>You can also remove the RNS 315 from its slot to check. Behind it, you’ll find a label with the RNS-315’s MAC address.<br/>If the MAC address contains only zeros (MAC: 00:00:00:00:00:00), your RNS-315 is not equipped with the Bluetooth module. </p>\n<figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/rns_315_j_mac_non-6328b9e5.webp\"/></figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/rns315_mac_oui-eed1a386.webp\"/></figure>\n</figure>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition, then run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/> 3 – Click on “<strong>Select”</strong>, then click on “<strong>Select</strong>”, then click on “<strong>Select</strong>”. <strong>Procedure:</strong> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket. <strong><strong>“37 – Navigation</strong></strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Coding 07</strong>”.</p>\n<p><strong>5</strong> – Select the “0” module and click on “Long Coding Helper”:</p>\n<p><em>Byte <strong>3</strong><br/>Bit <strong>5</strong>: Uncheck the “Telephone Transceiver inactive” box</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/RNS315_3C0-035-279_Module37_Byte3-74e93c9c.webp\"/></figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/rns-315-bt-8b82eb41.webp\"/></figure>","amarok-2h-add-daytime-running-lights-drl-to-odb":"<p><strong>Purpose:</strong> Allows you to enable or disable daytime running lights (DRL) in the ODB (MFA). (2011+)</p>\n<p><strong>Procedure </strong>: <br/>1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/>2 – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1 :</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Coding 07</strong>”.</p>\n<p><strong>5</strong> – Select the “0” module and click on “Long Coding Helper”:</p>\n<p>Byte <strong>15</strong>: Bit <strong>7</strong>: Check “Daytime Running Light (DRL) Active Adaptation (MFA+)”</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/drlmfag6-54cdc95d.webp\"/></figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/drlmfag62-c1d9cfb9.webp\"/></figure>","amarok-2h-adjusting-light-sensor-sensitivity":"<p><strong>Purpose: </strong>Adjusts the sensitivity of the light sensor.  </p>\n<p><strong>Procedure: </strong><br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Coding 07</strong>”.</p>\n<p><strong>5</strong> – Select the “2 EPIRBs” module from the drop-down list and click on “Long Coding Helper”:</p>\n<p><em>Byte <strong>0</strong>:  </em><br/><em>Bits <strong>3–4</strong>: Select from the drop-down list<br/>– 00 Normal light activation threshold<br/>– 08 Earlier light activation threshold (+20%)<br/>– 10 Light Activation Threshold earlier (+40%)<br/>– 08 Light Activation Threshold earlier (+60%)</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/Calc09-RLS-140kmhBit0-Octet0-4f74e4e9.webp\"/></figure>","amarok-2h-automatic-closing-of-windows-and-roof-in-case-of-rain":"<p><strong>Purpose</strong>: Automatically closes windows and sunroof when it rains.  </p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition, then run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/> 3 – Click on “<strong>Select</strong>”, then click on “<strong>09 – Cent. Elect.</strong>” . Switch on the ignition and run the VCDS program. 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>4</strong> – Click on “<strong>Coding 07</strong>”.</p>\n<p><strong>5</strong> – Click on “Long Coding Helper” :</p>\n<p><strong>6</strong> – In the window that appears, select:</p>\n<p><em>Byte <strong>4</strong>: </em><br/><em>Bit <strong>6: </strong> Check “Rain closing active”.</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/4A6D5E39-CE5A-476F-995D-444CD637E3AD-af64c8a6.webp\"/></figure>\n<p><strong>Line 2 </strong>:</p>\n<p><strong>3</strong> – Click on “<strong>Select</strong>” then click on “<strong>09 – Cent. Elect.</strong>” .</p>\n<p><strong>4</strong> – Click on “<strong>Coding 07</strong>”.</p>\n<p><strong>5</strong> – Select the “RLS” module and click on “Long Coding Helper”:</p>\n<p><em>Byte <strong>4</strong>: </em><br/><em>Bit <strong>2: </strong> Check “Rain closing active”.</em></p>","amarok-2h-automatic-door-locking":"<p><strong>Purpose: </strong>to set automatic door locking from 15km/h.  </p>\n<p><strong>Procedure: </strong><br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Coding 07</strong>”.</p>\n<p><strong>5</strong> – Select the “0” module and click on “Long Coding Helper”:</p>\n<p><em>Byte <strong>0</strong>: </em><br/><em>Bit <strong>4</strong>: Check “Auto-Lock (Automatic Locking above 15 km/h)”.</em><em><br/></em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/6R0-937-088-B_Module09_Byte0-87553eca.webp\"/></figure>","amarok-2h-automatic-door-locking-after-30s":"<p><strong>Purpose: </strong>to set automatic door unlocking when the vehicle has been unlocked but no doors have been opened for 30 seconds.  </p>\n<p><strong>Procedure: </strong><br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Coding 07</strong>”.</p>\n<p><strong>5</strong> – Select the “0” module and click on “Long Coding Helper”:</p>\n<p><em>Byte <strong>4</strong>: </em><br/><em>Bit <strong>5</strong>: Uncheck “Central Locking Re-locking (after 30 seconds) active”</em><em><br/></em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/6R0-937-088-B_Module09_Byte4-6c468b48.webp\"/></figure>","amarok-2h-automatic-door-unlocking":"<p><strong>Purpose: </strong>to configure automatic door unlocking when the ignition key is removed.  </p>\n<p><strong>Procedure: </strong><br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Coding 07</strong>”.</p>\n<p><strong>5</strong> – Select the “0” module and click on “Long Coding Helper”:</p>\n<p><em>Byte <strong>0</strong>: </em><br/><em>Bit <strong>3</strong>: Check “Auto-Unlock (Unlocking when Removing the Ignition Key)”.</em><em><br/></em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/6R0-937-088-B_Module09_Byte0-87553eca.webp\"/></figure>","amarok-2h-automatic-headlamp-activation-from-140-km-h":"<p><strong>Purpose: </strong>to automatically switch on the lights when the vehicle is travelling at over 140 km/h. </p>\n<p>(The lights will automatically go out if the vehicle is travelling at less than 60 km/h) </p>\n<p><strong>Procedure: </strong><br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Coding 07</strong>”.</p>\n<p><strong>5</strong> – Select the “2 EPIRBs” module from the drop-down list and click on “Long Coding Helper”:</p>\n<p>Byte <strong>0</strong>: <br/>Bit <strong>0</strong>: Check “Highway Light Function active above (140kph/90mph)”. </p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/Calc09-RLS-140kmhBit0-Octet0-4f74e4e9.webp\"/></figure>","amarok-2h-automatic-headlamp-activation-in-the-event-of-rain":"<p><strong>Purpose:</strong> to automatically turn on the lights when it’s raining and the wipers have been triggered.  </p>\n<p><strong>Procedure: </strong> <br/><strong>1</strong> – With the engine off and the ignition switched off, connect your official VAG-COM VCDS cable to the computer, then connect the other end to your vehicle’s diagnostic port.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Coding 07</strong>”.</p>\n<p><strong>5</strong> – Select the “2 EPIRBs” module from the drop-down list and click on “Long Coding Helper”:</p>\n<p>Byte <strong>0</strong> Bit<strong> 1 </strong>: Check “Rain Light Function Active”.  </p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/Calc09-RLS-140kmhBit0-Octet0-4f74e4e9.webp\"/></figure>","amarok-2h-change-number-of-flashes-comfort-flashers":"<p><strong>Purpose:</strong> to change the number of flashes after activating the comfort indicators.  <br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click “ <strong>Select</strong>,” then click “ <strong>09 – Cent. Elect.”</strong><br/><br/><strong>4 – </strong>Click on<strong> “Adaptation – 10” </strong></p>\n<p>5 – Select<strong> Channel 43</strong> (Lights: Comfort Turn Signals (Cycles) from the drop-down list)</p>\n<p><em>Choose a value between 1 and 5</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/6R0-937-088-B_Module09_Adaptation_channel43-3a96f44b.webp\"/></figure>","amarok-2h-change-odb-language":"<p><strong>Purpose:</strong> Select the language of your on-board computer.  <br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“17 – Instruments</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>5</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Language Version</strong>”.<br/><br/><strong>6</strong> – Select language from second value list  </p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/886F4702-2DBC-4C30-8716-D4D05CCE1338-da4cd84c.webp\"/></figure>","amarok-2h-change-the-theme-of-rcd-rns-510":"<p><strong>Purpose:</strong> to change the display theme of the RCD 510 and RNS 510.  </p>\n<p><strong>Procedure: </strong><br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1</strong>:</p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>” then click on<strong>“37 – Navigation</strong>” for RNS510 and “<strong>56 – Radio</strong>” for RCD510.</p>\n<p><strong>4</strong> – Click on<strong>“Coding 07</strong>” then “<strong>Long Coding Helper</strong>”.</p>\n<p><strong>5</strong> – Select Byte<strong> 7</strong></p>\n<p><em>Bit <strong>4-5</strong>: Select from 3 themes</em><br/><em>“00 Display Variant: Highline</em><br/><em>“10 Display Variant: Sportsline</em><br/><em>“20 Display Variant: Premium</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/2B758E5F-ACB4-418C-BBBB-B61B0F3A298B-186113f1.webp\"/></figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/69C76009-6EC7-465A-A676-8E39BA840A6B-6689b9e0.webp\"/><figcaption>Highline</figcaption></figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/3A58F148-9FBB-4DD8-BF05-E03A5351E3A8-e9b6cb9b.webp\"/><figcaption>Sportsline</figcaption></figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/4894A3B7-2ED2-4A75-9D46-CA3BFCF5A76C-8fb8de15.webp\"/><figcaption>Premium</figcaption></figure>\n<p>Exit the module and save your changes. The RCD / RNS 510 must now be restarted for the changes to take effect. Press both arrows and the star for 6s.  </p>","amarok-2h-coming-leaving-home-with-fog-lamps":"<p><strong>Purpose: </strong>Enables fog lamps to be used for Coming Home and Leaving Home.  </p>\n<p><strong>Procedure: </strong><br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Coding 07</strong>”.</p>\n<p><strong>5</strong> – Select the “0” module and click on “Long Coding Helper”:</p>\n<p>Byte <strong>13</strong>:<br/>Bit<strong> 6</strong>: Uncheck “Coming-Home (CH) / Leaving-Home (LH) Variant (0 = Fog Lights / 1 = Low Beam)”.</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/6R0-937-088-B_Module09_Byte13-092427d2.webp\"/></figure>","amarok-2h-coming-leaving-home-with-the-xenons":"<p><strong>Purpose: </strong>Allows xenon (or halogen) lights to be used for Coming Home and Leaving Home.  </p>\n<p><strong>Procedure: </strong><br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Coding 07</strong>”.</p>\n<p><strong>5</strong> – Select the “0” module and click on “Long Coding Helper”:</p>\n<p><em>Byte <strong>13</strong>: </em><br/><em>Bit <strong>6</strong>: Check “Coming-Home (CH) / Leaving-Home (LH) Variant (0 = Fog Lights / 1 = Low Beam)”.</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/6R0-937-088-B_Module09_Byte13-092427d2.webp\"/></figure>","amarok-2h-corner-lights":"<p><strong>Purpose:</strong> Allows you to turn on the cornering lights along with the fog lights.  <br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click “ <strong>Select</strong>,” then click “ <strong>09 – Cent. Elect.”</strong><br/><br/><strong>4 – </strong>Click on<strong> “Coding – 07” </strong></p>\n<p><strong>5</strong> – Select module “0” and click “Long Coding Helper”:</p>\n<p><em><strong>Byte 12: </strong></em><br/><em>Bit <strong>6</strong>: Check <strong>“Turn/Cornering Lights</strong> installed/active”</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/6R0-937-088-B_Module09_Byte12-011f47aa.webp\"/></figure>","amarok-2h-corner-lights-with-turn-signal":"<p><strong>Purpose:</strong> Enables the cornering lights to turn on along with the fog lights when the turn signal is activated.  <br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click “ <strong>Select</strong>,” then click “ <strong>09 – Cent. Elect.”</strong><br/><br/><strong>4 – </strong>Click on<strong> “Coding – 07” </strong></p>\n<p><strong>5</strong> – Select module “0” and click “Long Coding Helper”:</p>\n<p><em>Byte <strong>21: </strong></em><br/><em>Bit <strong>2</strong>: Check <strong>“Cornering/Turn Lights via Turn Signal active</strong> ”</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/6R0-937-088-B_Module09_Byte21-023ebd48.webp\"/></figure>","amarok-2h-daytime-running-light-deactivation-drl-with-handbrake-on":"<p><strong>Purpose: </strong>to deactivate the daytime running lights (DRL) when the handbrake is engaged.  </p>\n<p><strong>Procedure: </strong><br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Coding 07</strong>”.</p>\n<p><strong>5</strong> – Select the “0” module and click on “Long Coding Helper”:</p>\n<p><em>Byte <strong>11</strong>: </em><br/><em>Bit <strong>0</strong>: If this is a hidden bit, replace the last <strong>0</strong> on the right side of the binary number with <strong>a 1</strong>. (<strong>10001000</strong> =&gt; <strong>10001001</strong>)</em></p>","amarok-2h-deactivate-brake-pad-warning-light":"<p><strong>Purpose:</strong> Allows you to disable the brake pad wear warning light on the OBD (On-Board Diagnostics) system, for example, for brake pads without a sensor or if the sensor is malfunctioning / Brake Pad Warning Light Deactivation. </p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on ” <strong>Select”</strong>, then click on ” <strong>17 – Instruments</strong>“.</p>\n<p><strong>4</strong> – Cliquer sur « <strong>Codage – 07</strong> » puis cliquer sur « <strong>Assistant Codage Long</strong>« .</p>\n<p><strong>5</strong> – Select byte <strong>1</strong>: “<br/>” Then uncheck bit <strong>0: </strong> <strong>“Brakepad warning active/installed”</strong> </p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/6J0-920-802-J_Module17_Byte1-5e3ec890.webp\"/></figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/voyant-frein-d4619ec9.gif\"/></figure>","amarok-2h-deactivate-horn-without-ignition":"<p><strong>Purpose:</strong> to deactivate the horn when the ignition is off.  <br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.<br/><br/><strong>4</strong> – Click on <strong>“Coding – 07”</strong> then <strong>“Long Coding Helper”.</strong><br/><br/><strong>5</strong> – Select Byte <strong>17</strong>, Bit <strong>3</strong><br/><br/><strong>6</strong> – Check <strong>“Horn with” Terminal 15 OFF “inactive</strong></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/8B27B62E-B23B-4D69-A15C-C56C9A00FC14-c93db85d.webp\"/></figure>","amarok-2h-deactivate-windshield-washer-indicator":"<p><strong>Purpose:</strong> to deactivate the windshield washer indicator on the ODB (on-board computer).  </p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on “<strong>Select”</strong>, then click on “<strong>17 – Instruments</strong>”.</p>\n<p><strong>4</strong> – Click on “<strong>Coding – 07</strong>” then click on “<strong>Long Coding Helper</strong>” .</p>\n<p><strong>5</strong> – Select byte <strong>1</strong>:<br/>Then uncheck Bit <strong>2: </strong>“<strong>Washer Fluid warning active/installed</strong>”.  </p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/6J0-920-802-J_Module17_Byte1-5e3ec890.webp\"/></figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/laveglace-edc83d4f.webp\"/></figure>","amarok-2h-delete-alarm-belt":"<p><strong>Purpose:</strong> To suppress the audible alarm and the warning light on the speedometer when driving without a seatbelt.  </p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on “<strong>Select”</strong>, then click on “<strong>17 – Instruments</strong>”.</p>\n<p><strong>4</strong> – Click on “<strong>Coding – 07</strong>” then click on “<strong>Long Coding Helper</strong>” .</p>\n<p><strong>5</strong> – Select byte <strong>1</strong>:<br/>Then uncheck Bit <strong>1: </strong>“<strong>Seatbelt warning active/installed</strong>”.  </p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/6J0-920-802-J_Module17_Byte1-5e3ec890.webp\"/></figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/voyant_ceinture_de_securite-296648a9.webp\"/></figure>","amarok-2h-dimming-leds-with-turn-signals":"<p><strong>Purpose:</strong> Maintains the brightness of the LEDs (DRLs) when the turn signals are on.</p>\n<p><strong>Procedure </strong>: <br/>1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/>2 – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1 :</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Coding 07</strong>”.</p>\n<p><strong>5</strong> – Select the “0” module and click on “Long Coding Helper”:</p>\n<p>Bytes <strong>23</strong>: <br/>Bit <strong>7: </strong> This is a hidden bit; you must replace the 0 with a 1 directly in “Binary” (the eighth 0 with a 1)</p>","amarok-2h-disable-bluetooth-connection-beep":"<p><strong>Purpose </strong>: Disables the beep when a device successfully connects to the car radio’s Bluetooth.  </p>\n<p><strong>Procedure </strong>: <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1 :</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“77 – Telephone</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Adaptation 10</strong>”.</p>\n<p><strong>5</strong> – Select “Bluetooth acknowledgement signal” from the value list</p>\n<p><strong>6 </strong>– Select <strong>“Off” </strong>from the second drop-down list</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/7P6-035-730-C_Module77_Adaptation_Bluetooth_acknow-580a5d47.webp\"/></figure>","amarok-2h-disable-parking-aid-beep":"<p><strong>Purpose:</strong> to deactivate the beep when reverse gear is engaged or when parking assistance is activated manually.  <br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click “ <strong>Select</strong>,” then click “10-Parking<strong>Assistance.”</strong><br/><br/><strong>4 – </strong>Click on<strong> “Adaptation – 10” </strong></p>\n<p><strong>5</strong> – Select <em>“Parking Aid Activation Tone</em> ” from the drop-down list<strong>:</strong></p>\n<p><em>Select <strong>“Off” from </strong>the second drop-down list</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/6J0-919-475-B_Module10_Adaptation_Parking_aid_acti-4dbee393.webp\"/></figure>","amarok-2h-door-lock-unlock-confirmation-beep-horn":"<p><strong>Purpose: </strong>to set confirmation of door locking/unlocking with beep (alarm) or horn.  </p>\n<p><strong>Procedure: </strong><br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Coding 07</strong>”.</p>\n<p><strong>5</strong> – Select the “0” module and click on “Long Coding Helper”:</p>\n<p><em>Byte <strong>5</strong>: </em><br/><em>Bit <strong>1</strong>: Tick “Acoustical Locking Confirmation (Horn) active”.</em><br/><em>Bit <strong>4</strong>: Tick “Acoustical Unlocking Confirmation (Horn) active”. </em><br/><em>Bit <strong>7</strong>: Tick “Anti-Theft-System Activation Acoustical Confirmation (Horn) active”.</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/6R0-937-088-B_Module09_Byte5-90daaa01.webp\"/></figure>","amarok-2h-door-lock-unlock-confirmation-turn-signal":"<p><strong>Purpose: </strong>Used to set up confirmation of door locking using the indicators.  </p>\n<p><strong>Procedure: </strong><br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Coding 07</strong>”.</p>\n<p><strong>5</strong> – Select the “0” module and click on “Long Coding Helper”:</p>\n<p><em>Byte <strong>5</strong>: </em><br/><em>Bit <strong>0</strong>: Check “Locking/Unlocking Optical Confirmation (Turn Signal) active”.</em><em><br/></em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/6R0-937-088-B_Module09_Byte5-90daaa01.webp\"/></figure>","amarok-2h-enable-bluetooth-audio-a2dp":"<p><strong>Purpose </strong>: Enables Bluetooth audio (A2DP).  </p>\n<p>You can listen to music from your A2DP-compatible phone or mp3 player.  </p>\n<p><strong>Procedure </strong>: <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1 :</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“77 – Telephone</strong>”.</p>\n<p><strong>4</strong> – Click on<strong> “Coding – 07”</strong> then<strong> “Long Coding Helper”.</strong></p>\n<p><strong>5 </strong>– <em>Byte <strong>4</strong>: </em><br/><em>Bit <strong>0: </strong> Uncheck <strong>“Multimedia Function (Bluetooth Audio) inactive”.</strong></em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/D836B768-D607-4E70-92E6-06200694DE00-4d4d00be.webp\"/></figure>","amarok-2h-activate-driving-school-mode-rcd-210-rcd-310":"<p><strong>Purpose:</strong> Adds a “Driving School” mode view to the RCD 210 / RCD 310 or the Discover MIB2 PQ, which displays turn signals, speed, and more… (Also ideal for accompanied driving) <br/><br/><br/><strong>Procedure:</strong> <br/><strong>1</strong> – With the engine off and the ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostic port. <br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<hr/>\n<h4>RCD 210 / RCD 310</h4>\n<p><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click “<strong>Select</strong>,” then click “<strong>56 – Radio</strong>.”<br/><br/><strong>4</strong> – Click “<strong>Adaptation – 10</strong>.”<br/><br/><strong>6</strong> – At the very top of this page, there is a drop-down menu.<br/>From this drop-down menu, select “<strong>Channel 2</strong>.”<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu toward the bottom<br/>of the page.<br/>From this menu, select “<strong>1</strong>” and then confirm.</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/golf6_golf_vi_fahrschulfunktion-5b883ac1.webp\"/></figure>\n<hr/>\n<h4>Discover MIB2 PQ:</h4>\n<p><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong> then click on<strong>“5F – Electr. information</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“20103</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Vehicule function list CAN-Driving_school</strong>“.<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu at the bottom<br/>of the page.<br/>On this menu, select<strong>“active</strong>” and confirm.<br/><br/><strong>Line 2:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong> then click on<strong>“5F – Electr. information</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“20103</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Vehicule menu operation-menu_display_driving_school</strong>“.<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu at the bottom<br/>of the page.<br/>On this menu, select<strong>“active</strong>” and confirm.<br/><br/><strong>Line 3:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong> then click on<strong>“5F – Electr. information</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“20103</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Vehicule menu operation-menu_display_driving_school_over_threshold_high</strong>“.<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu at the bottom<br/>of the page.<br/>On this menu, select<strong>“active</strong>” and confirm.</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/IMG_6384-e21a59b4.webp\"/></figure>","amarok-2h-flash-mode-lights-during-emergency-braking":"<p><strong>Purpose</strong>: activates the brake/turn signal lights in flash mode during emergency braking.  </p>\n<p><strong>Procedure: </strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket. <br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Coding 07</strong>”.</p>\n<p><strong>5</strong> – Select the “0” module and click on “Long Coding Helper”:</p>\n<p><em>Byte <strong>12</strong>: </em><br/><em>Bit <strong>3</strong>: Check<em>“ </em> Emergency Flashing (<em>Turn Signals) active” </em> (to activate the turn signals)</em><br/><em>Bit <strong>4</strong>: Check “Emergency Brake Flashing (Brake Light) active” (to activate the brake lights)</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/6R0-937-088-B_Module09_Byte12-2c0d5984.webp\"/></figure>","amarok-2h-hill-hold-control":"<p><strong>Purpose: Enables </strong>Hill Hold Control (Hill Start Assist).  </p>\n<p>Hill Hold Control maintains brake pressure for a few seconds after the brake pedal is held down for an extended period.</p>\n<p><strong>Procedure </strong>: <br/>1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/>2 – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1 :</strong></p>\n<p><strong>3</strong> – Click “<strong>Select</strong>,” then click “<strong>03 – ABS Brakes</strong>” (or “<strong>03 – ABS Brakes” </strong>).<br/><br/><strong>4</strong> – Click “<strong>Coding – 07</strong>,” then “<strong>Long Coding Helper</strong>“</p>\n<p><em>Byte <strong>16: </strong></em><br/><em>Bit <strong>3</strong>: Check “Hill Hold Control (HHC/PR-UG1/UG4) active/installed”</em></p>\n<p><strong>Line 2: Hill Hold Control Settings.</strong></p>\n<p><strong>3</strong> – Click “<strong>Select</strong>,” then click “<strong>03 – ABS Brakes</strong>” (or “<strong>03 – ABS Brakes” </strong>).<br/><br/><strong>4</strong> – Click “<strong>Adaptation – 10</strong>.”</p>\n<p>Select <strong>Channel 58</strong> (Hill Hold Control (HHC) from the drop-down list)</p>\n<p>Select a value:<br/>0 “normal”<br/>1 “earlier” (restarts with lower acceleration)<br/>2 “later” (restarts with higher acceleration)</p>","amarok-2h-lock-cd-dvd-eject-button-on-rns-510":"<p><strong>Purpose</strong>: locks/unlocks the RNS 510’s CD/DVD eject button.  </p>\n<p><em>Protection against theft of your navigation DVD.  </em></p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition, then run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/> 3 – Click on ” <strong>Select”</strong>, then click on ” <strong>Select</strong> ” and run the VCDS program. <strong><strong>37 – Navigation</strong></strong>” .</p>\n<p><strong>4</strong> – Click on “<strong>Adaptation – 10</strong>”.</p>\n<p><strong>5</strong> – Select <em><strong>Channel 43</strong> (Ejection Lock)</em> then set the value to <strong>1</strong> <em>(CD/DVD Ejection Lock active)</em></p>\n<p><em>Restart the RNS 510.</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/rns510-1024x821-d0438887.webp\"/></figure>","amarok-2h-needle-check":"<p><strong>Purpose:</strong> activates needle sweep when the car is started. (Needle Sweep)   </p>\n<p><strong>ATTENTION: Only compatible with models since 2012 </strong>(Compatible module: 6R0 920 860 K)  <br/></p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on “<strong>Select”</strong>, then click on “<strong>17 – Instruments</strong>”.</p>\n<p><strong>4</strong> – Click on “<strong>10-Adaptation</strong>” then in the window that appears, click on the drop-down menu to choose a channel and select the “<strong>Staging</strong>” channel, if unavailable select the “<strong>indicator_celebration</strong>” channel:</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/checkg6-9456b738.webp\"/></figure>\n<p><strong>5</strong> – In the “<strong>New value</strong>” box, click on the drop-down menu and select “<strong>active</strong>”. Once this new value has been entered, click on “<strong>Save</strong>”:</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/checkg62-c8918051.webp\"/></figure>","amarok-2h-ops-speed-camera-display-on-car-radio-screen":"<p><strong>Purpose:</strong> Enables the display of OPS speed cameras on the car radio screen.  </p>\n<p><strong><em>Please note: The vehicle must be equipped with a compatible car radio (RCD-310, RCD-510, RNS-315, RNS-510).</em></strong> </p>\n<p><strong>Procedure </strong>: <br/>1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/>2 – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1 :</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“10-Station assistance</strong>”.</p>\n<p><strong>4</strong> – Click “<strong>Security Access – 16</strong>,” then enter the code “<strong>71679</strong>“</p>\n<p><strong>5</strong> – Click on<strong>“Coding- 07</strong>”. then click on<strong>“Long Coding Helper</strong>”.</p>\n<p><strong>6 – </strong>Select <em>Byte<strong> 0</strong>: </em><br/><em>Bit <strong>4</strong>: Tick “Optical illustration active”.</em></p>","amarok-2h-parking-aid-beep-frequency-setting":"<p><strong>Purpose:</strong> Allows you to adjust the frequency of the rear beeps during parking assistance.  <br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click “ <strong>Select</strong>,” then click “10-Parking<strong>Assistance.”</strong><br/><br/><strong>4 – </strong>Click on<strong> “Adaptation – 10” </strong></p>\n<p><strong>5</strong> – Select <em>“Speaker frequency for rear parking aid</em> ” from the drop-down list<strong>:</strong></p>\n<p><em>Select</em>a frequency from <em>Stage 1</em> (Low) to <em>Stage 9</em> (High) from the second drop-down list</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/6R0_Module10_Adaptation_speaker-frequency_for_rear-a3ec7081.webp\"/></figure>","amarok-2h-programming-a-remote-control":"<p><strong>Purpose:</strong> Allows you to program the remote controls that will be used with the vehicle for central locking and unlocking.  </p>\n<p>⚠️ <strong>WARNING:</strong> This procedure does not allow you to program remote controls with the vehicle’s immobilizer.<br/>If your vehicle is equipped with a <strong>KESSY</strong> remote control <strong>(05 – Access/Ignition Authorization)</strong>, you cannot program a new remote control using this procedure.</p>\n<p><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click <strong>“Select</strong>,” then click “ <strong><strong>“09 – Cent. Elect.”</strong></strong>.”<br/><br/><strong>4 </strong>– Click on “<strong>Adaptation – 10</strong>”.  </p>\n<p><strong>5</strong> – Select <strong>Channel 01 ( </strong>“Remote Control Adaptation” from the drop-down list)</p>\n<p>Enter the number of keys to program, then click <strong>Save</strong>.<br/>Next, press the <strong>Unlock</strong> button on each remote control to be programmed for at least 1 second. The flashing lights will confirm the process.<br/>All keys must be programmed in a single session, one after the other.<br/>Programming all keys must not take longer than <strong>15 seconds</strong>.<br/>You can add up to <strong>7 remote controls</strong>. If the <strong>[Test]</strong> and/or <strong>[Save]</strong> buttons are grayed out and unclickable, the module likely has all 7 slots filled; delete the remote controls using the <strong>“Reset Remote Controls”</strong> tutorial.  </p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/programmertelecommande-51bf4068.webp\"/></figure>","amarok-2h-resetting-the-remote-controls":"<p><strong>Purpose:</strong> Resets the settings for all remote controls associated with the vehicle. </p>\n<p><strong>⚠️ WARNING:</strong> After completing this procedure, all remote controls will be deleted and will need to be reprogrammed using the <strong>“Program a Remote Control”</strong> tutorial <strong>.</strong><br/>If your vehicle is equipped with a <strong>KESSY</strong> remote control <strong>(05 – Access/Start Authorization)</strong>, you cannot delete the remote controls using this procedure.</p>\n<p><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click <strong>“Select</strong>,” then click “ <strong><strong><strong>“09 – Cent. Elect.”</strong></strong></strong>.”<br/><br/><strong>4 </strong>– Click on “<strong>Adaptation – 10</strong>”.  </p>\n<p><strong>5</strong> – Select <strong>Channel 00</strong></p>\n<p><em>Set the value to <strong>0</strong> and save</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/6Q0-959-433-E_Module46_Adaptation_Channel00-caced031.webp\"/></figure>","amarok-2h-retrofit-heated-mirrors":"<p><strong>Function</strong>: Turns on the heated and defrosting side mirrors.  </p>\n<p>The vehicle must be equipped with heated side mirrors. Or, for the installation of heated side mirrors (retrofit)   </p>\n<p><strong>Procedure:</strong> <br/>1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/>2 – Switch on the ignition, then run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/>3 – Click on ” <strong>Select</strong> “, then click on ” <strong>09 – Cent. Elect.</strong>” . Switch on the ignition and run the VCDS program. 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>4</strong> – Click on “ <strong>Code 07.”</strong></p>\n<p><strong>5</strong> – Click on “Long Coding Helper” :</p>\n<p><strong>6</strong> – In the window that appears,</p>\n<p><em>Byte <strong>14: </strong></em><br/><em>Bit<strong> 3</strong>: Check “Mirror Heating ON while rear Window Heater ON”<br/>Bit <strong>7</strong>: Check “Heated Outside Mirrors installed”</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/6R0-937-088-B_Module09_Byte15-1c45d71d.webp\"/></figure>","amarok-2h-selective-door-unlocking":"<p><strong>Purpose: Allows </strong>you to configure selective door unlocking. <br/></p>\n<p>When unlocking the vehicle, only the driver’s door is unlocked. To unlock all doors, press the remote control’s unlock button twice.   </p>\n<p><strong>Procedure: </strong><br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Coding 07</strong>”.</p>\n<p><strong>5</strong> – Select the “0” module and click on “Long Coding Helper”:</p>\n<p><em>Byte <strong>0</strong>: </em><br/><em>Bit <strong>0</strong>: Check “Selective Central Locking (Single Door Locking) active”</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/6R0-937-088-B_Module09_Byte0-87553eca.webp\"/></figure>","amarok-2h-speed-limit-display-rns-510":"<p><strong>Purpose </strong>: to display the speed limit on the RNS 510 navigation screen.  </p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1</strong>:</p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>” then click on<strong>“37 – Navigation</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Coding 07</strong>”. Then “<strong>Long Coding Helper</strong>”.</p>\n<p><strong>5</strong> – Select Byte<strong> 7</strong><br/>Activate Bit <strong>2</strong>: Speed Threshold for Destination Input active</p>\n<p>+ use voice command to activate Bit 3: Speed Threshold for Speech Destination Input active</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/2B758E5F-ACB4-418C-BBBB-B61B0F3A298B-186113f1.webp\"/></figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/rns510speed-9dcbaa67.webp\"/></figure>","amarok-2h-start-stop-deactivation":"<p><strong>Purpose:</strong> to deactivate Start and Stop completely. For phase 1 and 2.  <br/><br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<h3>Phase 1 (2010/2016):</h3>\n<p><strong><em>Only compatible with Gateway 7N0! Temperature deactivation method. </em></strong> </p>\n<p><br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“19 – CAN Gateway</strong>”.<br/><br/><strong>4</strong> – Click on <strong>“Long Adaptation – 0A”</strong>.<br/><br/><strong>5</strong> – Select Channel<strong>“13</strong><br/><br/><strong>6</strong> – In new value, select<strong>“D02000</strong>” (default value = <strong>002000</strong>) then validate.<br/></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/gof6startstop-1024x528-699ec970.webp\"/></figure>\n<hr/>\n<h3>Phase 2 (Facelift) (2016/2022) :</h3>\n<p><strong>Method 1 (voltage method, recommended):</strong></p>\n<p><strong>VCDS :  </strong><br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“19 – CAN Gateway</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>5</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose <strong>“Limite de tension de départ marche/arrêt” / “Start/Stop voltage limit”</strong>.<br/><br/><strong>6</strong> – On this same page, there is a second drop-down menu, but at the bottom<br/>of the page.<br/>On this menu, select<strong>“12</strong>” (default value = <strong>7.6V</strong>) then validate.<br/></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/vw_start_stop_change_voltage_limit_value-a50bc29b.webp\"/></figure>\n<p><strong>OBDeleven:</strong></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/obdelevenstartstoptension-ec0170bc.webp\"/></figure>\n<p><strong>Method 2 (Temperature method):</strong></p>\n<p><strong>VCDS :</strong></p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“19 – CAN Gateway</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Adaptation – 10</strong>”.</p>\n<p><strong>5</strong> – On this page, at the top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Start/Stopp Auntemperaturvorgabe-Minimaltemperatur</strong>”.</p>\n<p><strong>6</strong> – On this same page, there is a second drop-down menu at the bottom<br/>of the page.<br/>Select<strong>“50</strong>” (default value = <strong>-50.0</strong>) and confirm.</p>\n<p><strong>Line 2:</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“19 – CAN Gateway</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Adaptation – 10</strong>”.</p>\n<p><strong>5</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Start/Stopp Auntemperaturvorgabe-Maximaltemperatur</strong>”.</p>\n<p><strong>6</strong> – On the same page, you’ll find a second drop-down menu at the bottom<br/>of the page.</p>\n<p><strong>OBDeleven:</strong></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/obdelevenstarstoptemp-494422ad.webp\"/></figure>","amarok-2h-suppress-odb-error-led-license-plate-illumination":"<p><strong>Purpose:</strong> Eliminates the error on the ODB when replacing original license plate light bulbs with non-error LEDs.  <br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on “<strong>Select</strong>” then click on “<strong>09 – Cent. Elect.</strong>” .<br/><br/><strong>4 </strong>– Click on “<strong> Coding – 07 </strong>”.</p>\n<p><strong>5</strong> – Select the “0” module and click on “Long Coding Helper”:</p>\n<p><em><strong>Byte 11 </strong>: </em><br/><em>Bit <strong>7</strong>: Uncheck “</em>Lamp diagnotics for Lisense Plate Light active<em>”.</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/6R0-937-088-B_Module09_Byte11-e6e5cf22.webp\"/></figure>","amarok-2h-tear-wiping":"<p><strong>Purpose:</strong> to activate the windshield wipers once more after using the windshield washer, in order to remove any remaining water from the windshield.  </p>\n<p><strong>Procedure:</strong> <br/>1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/>2 – Switch on the ignition, then run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/>3 – Click on ” <strong>Select</strong> “, then click on ” <strong>09 – Cent. Elect.</strong>” . Switch on the ignition and run the VCDS program. 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>4</strong> – Click on <strong>“Coding – 07”</strong> then <strong>“Long Coding Helper”.</strong></p>\n<p><strong>5</strong> – Select byte <strong>14</strong>, <br/>Bit <strong>4</strong>, Check <strong>“Tear Wiping Active”</strong>.</p>"};
